import {PRODUCTS} from './data.mjs';
import {analyze,mergeQuery,recommend,guardrails,compareProducts,money,localPrice} from './engine.mjs';
export function namedProducts(text,products=PRODUCTS){const v=text.toLowerCase();const rows=products.flatMap(p=>{const aliases=[p.name,p.zh,p.name.replace(/ Headphones$| Earbuds$| Speaker$| Camera$/,'')].filter(x=>x.length>5);const token=aliases.sort((a,b)=>b.length-a.length).find(x=>v.includes(x.toLowerCase()));return token?[{p,token}]:[];});return rows.filter(x=>!rows.some(y=>y.p.id!==x.p.id&&y.token.length>x.token.length&&y.token.toLowerCase().includes(x.token.toLowerCase()))).sort((a,b)=>v.indexOf(a.token.toLowerCase())-v.indexOf(b.token.toLowerCase())).map(x=>x.p.id);}
export function runShoppingTurn(text,context={},products=PRODUCTS,{market='US',language='zh',extracted=null,strategy='match',weights=undefined}={}){
 const en=language==='en',raw=extracted||analyze(text,market),q=mergeQuery(context.query,raw),trace=[];
 trace.push({tool:'understand_request',detail:en?'Extract preferences and retain explicit constraints':'抽取本轮需求并继承明确的购物约束'});
 const named=namedProducts(text,products);const last=context.lastComparison?.length?context.lastComparison:context.lastProducts||[];
 let ids=named.length?named:last;if(!named.length&&/前两|first two/i.test(text))ids=last.slice(0,2);const ordinal=text.match(/第([一二三123])|\b(first|second|third)\b/i);if(ordinal){const n=ordinal[1]?{'一':0,'二':1,'三':2,'1':0,'2':1,'3':2}[ordinal[1]]:{first:0,second:1,third:2}[ordinal[2].toLowerCase()];ids=(context.lastProducts||[])[n]?[(context.lastProducts||[])[n]]:[];}
 const next={...context,query:q,lastProducts:context.lastProducts||[],lastComparison:context.lastComparison||[]};
 const finish=(kind,reply,extra={})=>({kind,reply,query:q,context:next,trace,products:[],...extra});
 if(raw.intent==='after_sales'){trace.push({tool:'store_policy',detail:'30-day returns; order eligibility requires store confirmation'});return finish('policy',en?'I can explain the return policy. The demo store offers 30-day returns, but your order date and item condition must be checked by the store. I cannot process a refund here.':'我可以先说明退货政策：演示店铺提供30天退货，具体资格需要店铺核验订单日期与商品状态。这里不能直接办理退款。');}
 if(/加入.*(?:车|购物)|加购|放.*购物车|add.{0,50}cart/i.test(text)){
  const id=ids.length===1?ids[0]:context.lastProducts?.length===1?context.lastProducts[0]:null,p=products.find(p=>p.id===id);
  if(!p)return finish('clarify',en?'Which product would you like to add? Choose a product card or say “add the first one”.':'你想加入哪一款？可以点击商品卡，或说“把第一款加入购物车”。');
  const v=p.variants.find(v=>text.toLowerCase().includes(v.name.toLowerCase())||text.includes(v.zh));trace.push({tool:'get_product_details',detail:p.name+' · variant and stock check'});
  next.focusProductId=p.id;return finish('cart_action',en?`Let’s add ${p.name}. ${v?'I found your selected color.':'Please choose a color before adding it.'}`:`为你选择了 ${p.name}。${v?'已识别你指定的颜色。':'请先确认颜色，再加入购物车。'}`,{products:[p],action:{type:v?'add_cart':'choose_variant',productId:p.id,variantId:v?.id}});
 }
 const policy=raw.intent==='policy'||/shipping|deliver|多久到|几天到|运费|配送|保修|退货政策/i.test(text);
 if(policy){const p=products.find(p=>p.id===ids[0]);trace.push({tool:'store_policy',detail:p?.policy||'Demo store return policy'});if(p){trace.push({tool:'get_delivery_estimate',detail:p.days[market]+' days · estimate'});next.focusProductId=p.id;}return finish('policy',p?(en?`${p.name}: ${p.policy}. Demo delivery estimate to ${market}: ${p.days[market]} days. The store must confirm delivery and final shipping fees.`:`${p.name} 的演示政策：${p.policy}。在 ${market} 市场的演示配送时效约 ${p.days[market]} 天，实际到货及运费以店铺结账页确认为准。`):(en?'The demo store offers 30-day returns. Warranty and delivery vary by product; select a product for exact demo details.':'演示店铺提供30天退货；保修和配送时效因商品而异。你可以选定一款商品，我再帮你查具体信息。'),{products:p?[p]:[]});}
 const specQuestion=/续航|battery|更轻|重量|weight|参数|详情|detail|哪款.*长|longest|lighter/i.test(text)&&ids.length&&raw.budget===null&&(!raw.category||named.length===1);
 const compare=/比较|对比|compare|\bvs\b|versus/i.test(text)||(/哪款|哪个|which/i.test(text)&&ids.length>0);
 if(specQuestion||compare||named.length>=2){
  if(ids.length<2&&!specQuestion)return finish('clarify',en?'Select at least two products to compare, or ask for recommendations first.':'请先选至少两款商品进行比较，也可以先让我推荐几款。');
  const list=compareProducts(ids,market,products);trace.push({tool:'compare_products',detail:list.map(p=>p.name).join(' / ')});next.lastComparison=list.map(p=>p.id);next.lastProducts=list.map(p=>p.id);
  const battery=list.filter(p=>p.specs.battery).sort((a,b)=>b.specs.battery-a.specs.battery),light=list.filter(p=>p.specs.weight).sort((a,b)=>a.specs.weight-b.specs.weight);const focus=/更轻|重量|weight|lighter/i.test(text)?light[0]:battery[0];
  const reply=specQuestion&&focus?(en?`${focus.name} has ${focus.specs.battery?focus.specs.battery+'h demo battery life':''} and weighs ${focus.specs.weight}g. See the comparison for the trade-offs.`:`按演示商品参数，${focus.name}${focus.specs.battery?'续航为 '+focus.specs.battery+' 小时，':''}重量为 ${focus.specs.weight}g。你可以在下表比较价格、续航、重量与配送。`):(en?'Here is a comparison using verified demo catalog fields. Choose based on your budget and priorities; missing specs are shown as unknown.':'我把候选商品放在一起比较。价格、续航、重量和库存都来自演示商品池；没有的参数会显示为未提供。');
  return finish('comparison',reply,{products:list});
 }
 const sort=/便宜|低价|cheaper|lowest price/i.test(text)?'price':/续航优先|longest battery/i.test(text)?'battery':'match';const r=recommend(q,products,{sort,strategy,weights});trace.push({tool:'recall_candidates',detail:Object.entries(r.channels).filter(([,ids])=>ids.length).map(([k,ids])=>k+':'+ids.length).join(' · ')});trace.push({tool:'filter_candidates',detail:`${r.counts.recalled} recalled · ${r.counts.filtered} excluded · ${r.counts.eligible} eligible`});trace.push({tool:'rank_products',detail:`${strategy} · ${sort} · ${r.items.length} returned`});if(strategy==='diverse')trace.push({tool:'rerank_diversity',detail:'Greedy brand penalty · 12 points per previously selected same-brand item'});
 const checks=guardrails(q,r.items,products);trace.push({tool:'verify_constraints',detail:checks.map(c=>c.label+':'+(c.pass?'pass':'fail')).join(' · ')});
 if(checks.some(c=>!c.pass))return finish('blocked',en?'The results did not pass verification. Please refine your request.':'结果未通过约束检查，暂不展示推荐。请调整需求后再试。',{checks});
 next.lastProducts=r.items.map(p=>p.id);next.lastComparison=[];next.focusProductId=r.items.length===1?r.items[0].id:null;
 if(!r.items.length)return finish('empty',en?'No available product matches all your constraints. I have kept your budget and required features. Would you like to change the budget or product type?':'当前没有同时满足预算、品类和必要特性的在售商品。我保留了你的限制条件；你可以调整预算、品类或明确取消某个要求。',{checks,search:r});
 const first=r.items[0];return finish('recommendation',en?`I’d start with ${first.name} (${money(localPrice(first,market),market)}). These options fit your current constraints. You can compare them, ask about battery life, or tell me to find something cheaper.`:`先看 ${first.name}（${money(localPrice(first,market),market)}）。以下候选符合你当前的预算与商品要求。你可以继续说“比较前两款”“哪款续航更长”或“便宜一点”。`,{products:r.items,checks,search:r});
}
